import*as THREE from'three';import{materials}from'../../core/index.js';import{mesh,FACE,portQuaternion}from'../../modeling/parts.js';import{roundedRect,capsule}from'../../core/geometry.js';export{THREE,materials,mesh,FACE,portQuaternion,roundedRect,capsule};export const tau=Math.PI*2;
export const box=(p,s,at,m,n)=>mesh(p,new THREE.BoxGeometry(...s),m,at,n);
export const solid=(p,s,d,at,m,n)=>mesh(p,new THREE.ExtrudeGeometry(s,{depth:d,bevelEnabled:false,curveSegments:48}),m,at,n);
export function hole(s,x,y,r){const h=new THREE.Path();h.absarc(x,y,r,0,tau,false);s.holes.push(h);}
export function ring(p,r,i,d,at,m,n){const s=new THREE.Shape();s.absarc(0,0,r,0,tau,false);hole(s,0,0,i);return solid(p,s,d,at,m,n);}
export function cylinder(p,r,d,at,m,n){return mesh(p,new THREE.CylinderGeometry(r,r,d,64).rotateX(Math.PI/2),m,at,n);}
export function lathe(p,profile,at,m,n){const g=new THREE.LatheGeometry(profile.map(([r,z])=>new THREE.Vector2(r,z)),96).rotateX(Math.PI/2);const pos=g.attributes.position,raw=g.index,keep=[];for(let i=0;i<raw.count;i+=3){const a=new THREE.Vector3().fromBufferAttribute(pos,raw.getX(i)),b=new THREE.Vector3().fromBufferAttribute(pos,raw.getX(i+1)),c=new THREE.Vector3().fromBufferAttribute(pos,raw.getX(i+2));if(b.sub(a).cross(c.sub(a)).lengthSq()>1e-20)keep.push(raw.getX(i),raw.getX(i+1),raw.getX(i+2));}g.setIndex(keep);const ix=g.index;let v=0;for(let i=0;i<ix.count;i+=3){const a=new THREE.Vector3().fromBufferAttribute(pos,ix.getX(i)),b=new THREE.Vector3().fromBufferAttribute(pos,ix.getX(i+1)),c=new THREE.Vector3().fromBufferAttribute(pos,ix.getX(i+2));v+=a.dot(b.cross(c));}if(v<0){for(let i=0;i<ix.count;i+=3){const a=ix.getX(i+1);ix.setX(i+1,ix.getX(i+2));ix.setX(i+2,a);}g.computeVertexNormals();}return mesh(p,g,m,at,n);}
